var i=`0721-calulu`;var n=`world-0721`;var a=`AO`;var s=`central-africa`;var l=4;var o=56;var r={en:`Calulu`,ua:`Калулу`};var g={en:`Calulu is a Angola classic prepared with yellow onion, tomato, garlic, smoked mackerel. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Калулу, страва кухні країни Ангола зі складниками: жовта цибуля, помідор, часник, копчена скумбрія. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var m=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,200,`g`],[`tomato`,390,`g`],[`red-palm-oil`,60,`ml`],[`garlic`,4,`clove`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 40 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 40 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:40,i:[[`smoked-mackerel`,350,`g`],[`okra`,330,`g`],[`spinach`,300,`g`],[`water`,700,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`lemon-juice`,30,`ml`],[`table-salt`,null,`to_taste`]]}];var u={slug:i,id:n,country:`AO`,region:s,servings:4,minutes:56,title:r,text:g,steps:m};export{a as country,u as default,n as id,o as minutes,s as region,l as servings,i as slug,m as steps,g as text,r as title};